import fs from "node:fs/promises";
import {join} from "node:path";
import {pathToFileURL} from "node:url";
import assert from "node:assert/strict";
import {chromium} from "playwright-core";
const marker=JSON.parse(await fs.readFile(join(process.env.D6_RUN_ROOT,".d6-run.json")));
const browser=await chromium.launch({executablePath:"/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",headless:true});
const page=await browser.newPage({viewport:{width:1440,height:1000}});
try {
await page.goto(pathToFileURL(join(marker.source,"prototypes/d6/acceptance/index.html")).href);
await page.locator("video").evaluateAll(videos=>videos.forEach(video=>{video.preload="metadata";video.load()}));
await page.waitForFunction(()=>Array.from(document.querySelectorAll("video")).every(v=>v.readyState>=1||v.error),undefined,{timeout:20000});
const metadata=await page.locator("video").evaluateAll(videos=>videos.map(v=>({src:v.getAttribute("src"),duration:v.duration,width:v.videoWidth,height:v.videoHeight,error:v.error?.message})));
assert.ok(metadata.every(v=>v.duration>0&&!v.error),JSON.stringify(metadata));
const layout=[];
for(const width of [1440,390]){await page.setViewportSize({width,height:900});layout.push(await page.evaluate(()=>({width:innerWidth,scrollWidth:document.documentElement.scrollWidth})));assert.ok(layout.at(-1).scrollWidth<=width)}
await fs.writeFile(join(process.env.D6_RUN_ROOT,"prototypes/d6/acceptance/evidence/review-index.json"),JSON.stringify({metadata,layout,scope:"review artifact media playback and layout; not product visual acceptance"},null,2));
console.log("Review index media metadata and two viewport layouts passed");
}finally{await browser.close()}
